head.script:
// 담당 범위 : monthNames 가이드 전 항목 (con_monthNames 1개, pickerType 이 다른 Body Column 2개를 한 화면에서 비교)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > monthNames]<br/>inputType='calendar' 인 Column 에서 팝업 달력의 월 영역에 표시되는 월의 이름을 설정합니다.",
    "validation" : [
        "문자열 설정 시, 팝업 달력의 월 영역에 표시되는 월의 이름을 콤마(',')로 구분하여 설정합니다.",
        "문자열 설정 시, Column 의 pickerType 속성값과 관계없이 월에 해당하는 SelectBox 와 커스텀 UI 에 모두 적용됩니다.",
        "속성값을 설정하지 않으면 '1월,2월,3월...' 이 설정됩니다.",
        "Column 의 pickerType='selectbox' 일때 설정한 값이 12 개보다 적으면 값이 없는 월은 숫자로 표시됩니다.",
        "Column 의 pickerType='dynamic' 일때 설정한 값이 12 개보다 적으면 값이 없는 월은 undefined 로 표시됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (12개 영문)
    con_monthNames.setValue("Jan,Feb,Mar,Apr,May,Jun,Jul,Aug,Sep,Oct,Nov,Dec");

    // 달력 아이콘 / dynamic 상단 영역 클릭 시 결과 출력 (페이지 로딩 시 1회만 등록)
    document.addEventListener("click", scwin.onDocumentClick, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - selectDate  : inputType="calendar", pickerType="selectbox" (validation 1, 2, 3, 4)
//  - dynamicDate : inputType="calendar", pickerType="dynamic"   (validation 1, 2, 3, 5)
//  - 2개 Column 모두 monthNames = con_monthNames (미설정은 속성 자체를 넣지 않는다)
//  - 초기값 2026-10-01 (10월) : 3개만 설정 시 값이 없는 월이 상단 영역에 표시되도록 함
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 2개 Column 모두 같은 monthNames 설정, 날짜 값은 2026-10-01 (10월)\n[절차] Cell 클릭 -> 입력창 오른쪽 달력 아이콘 클릭 -> 팝업 달력 확인, dynamic Column 은 팝업 상단 연도/월 영역을 클릭해 월 선택 화면 확인\n[확인] 팝업이 열리거나 월 선택 화면으로 전환되면 결과창에 월 이름이 출력됩니다."', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cMonthNames = con_monthNames.getValue();
    let attrMonthNames = (cMonthNames === '') ? '' : ' monthNames="' + cMonthNames + '"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (calendar Column 바인딩 컬럼은 dataType="date")
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="selectDate" name="selectDate" dataType="date"></w2:column>';
    strDlt += '<w2:column id="dynamicDate" name="dynamicDate" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([{ "selectDate" : "20261001", "dynamicDate" : "20261001" }], false);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:420px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="pickerType=selectbox"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column2" value="pickerType=dynamic"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" id="selectDate" inputType="calendar" dataType="date" viewType="icon"'
        + ' calendarValueType="yearMonthDate" ioFormat="yyyyMMdd" displayFormat="yyyy-MM-dd" pickerType="selectbox"' + attrMonthNames + '></w2:column>';
    strTarget += '<w2:column width="200" style="" id="dynamicDate" inputType="calendar" dataType="date" viewType="icon"'
        + ' calendarValueType="yearMonthDate" ioFormat="yyyyMMdd" displayFormat="yyyy-MM-dd" pickerType="dynamic"' + attrMonthNames + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 화면에 열려 있는 target1 의 팝업 달력 render 반환 (없으면 null)
scwin.getOpenedCalendar = function () {
    if (typeof target1 === 'undefined' || !target1) {
        return null;
    }
    let cals = document.querySelectorAll("div.w2calendar[id*='G_" + target1.id + "__']");
    for (let i = 0; i < cals.length; i++) {
        if (cals[i].offsetWidth > 0 && cals[i].offsetHeight > 0) {
            return cals[i];
        }
    }
    return null;
}



// 달력 아이콘 클릭 -> 팝업 정보 출력 / dynamic 상단 연도/월 영역 클릭 -> 월 선택 화면 출력
scwin.onDocumentClick = function (e) {
    let elem = e.target;
    if (!elem || !elem.closest || typeof target1 === 'undefined' || !target1) {
        return;
    }
    let btn = elem.closest("button.w2inputCalendar_button");
    if (btn && btn.id.indexOf("G_" + target1.id + "__") >= 0) {
        setTimeout(scwin.printCalendarInfo, 300);
        return;
    }
    let header = elem.closest("[class*='w2calendar_picker_header_dynamic']");
    if (header && scwin.getOpenedCalendar()) {
        setTimeout(scwin.printMonthPicker, 300);
    }
}



// 팝업 달력이 속한 Column ID (팝업 id : ..._G_{gridId}__{colId}_calendar)
scwin.getCalendarColumnId = function (cal) {
    let m = cal.id.match(/__(.+?)_calendar/);
    return m ? m[1] : "";
}



// validation 1 ~ 5 판정 출력 : 팝업 달력이 열리면 월 SelectBox 항목 또는 dynamic 상단 영역 표시 텍스트
scwin.printCalendarInfo = function () {
    let cal = scwin.getOpenedCalendar();
    if (!cal) {
        return;
    }
    let colId = scwin.getCalendarColumnId(cal);
    let bottom = wf_body_bottom.getObj("scwin");

    if (colId === "dynamicDate") {
        // validation 5 : 상단 연도/월 영역 (값이 없는 월은 undefined)
        let entity = cal.querySelector("[class*='w2calendar_picker_header_dynamic_entity']");
        let parts = [];
        if (entity) {
            for (let i = 0; i < entity.children.length; i++) {
                parts.push(entity.children[i].textContent);
            }
        }
        bottom.setReturnValue(colId + " 상단 연도/월 영역 : " + parts.join(" "));
    } else {
        // validation 4 : 월 SelectBox 항목 (값이 없는 월은 숫자)
        let monthSel = WebSquare.util.getComponentById(cal.id + "_selectbox_month");
        let labels = [];
        if (monthSel) {
            for (let i = 0; i < monthSel.getItemCount(); i++) {
                labels.push(monthSel.itemArr[i].label);
            }
        }
        bottom.setReturnValue(colId + " 월 SelectBox : " + labels.join(", "));
    }
}



// validation 2 판정 출력 : dynamic 월 선택 화면(커스텀 UI) 의 월 이름
scwin.printMonthPicker = function () {
    let cal = scwin.getOpenedCalendar();
    if (!cal) {
        return;
    }
    let cells = cal.querySelectorAll("[class*='w2calendar_picker_cell']");
    let labels = [];
    for (let i = 0; i < cells.length; i++) {
        if (cells[i].offsetWidth > 0 && cells[i].textContent !== "") {
            labels.push(cells[i].textContent);
        }
    }
    if (labels.length === 12) {
        wf_body_bottom.getObj("scwin").setReturnValue(scwin.getCalendarColumnId(cal) + " 월 선택 화면 : " + labels.join(", "));
    }
}
